const items = $input.all();
const msg = items[0].json;

const text = msg.text || msg.snippet || '';
const subject = msg.Subject || msg.subject || '';
const from = msg.From || msg.from || '';
const source = msg.source || 'gmail';

const attachments = [];

if (msg.attachments && Array.isArray(msg.attachments)) {
  msg.attachments.forEach(a => {
    attachments.push({
      name: a.filename || a.name || 'unknown',
      type: a.mimeType || '',
      size: a.size || 0
    });
  });
}

try {
  const binaryKeys = Object.keys($binary || {});
  binaryKeys.forEach(key => {
    const b = $binary[key];
    if (b && b.fileName) {
      attachments.push({
        name: b.fileName,
        type: b.mimeType || '',
        size: b.fileSize || 0
      });
    }
  });
} catch(e) {}

if (msg.payload?.parts) {
  const scanParts = (parts) => {
    parts.forEach(part => {
      if (part.filename && part.filename.length > 0) {
        attachments.push({
          name: part.filename,
          type: part.mimeType || '',
          size: part.body?.size || 0
        });
      }
      if (part.parts) scanParts(part.parts);
    });
  };
  scanParts(msg.payload.parts);
}

const attachmentList = attachments.length > 0
  ? attachments.map(a => `• ${a.name} (${a.type})`).join('\n')
  : 'Вложений не обнаружено';

const docList = [
  '- contract: "Контракт" / "Contract"',
  '- invoice: "Инвойс / Проформа" / "Invoice / Proforma"',
  '- packing_list: "Упаковочный лист" / "Packing List"',
  '- certificate: "Сертификат соответствия" / "Certificate CCC"',
  '- export_declaration: "Экспортная декларация EX-1" / "Export Declaration"',
  '- business_license: "Бизнес-лицензия" / "Business License"',
  '- export_license: "Экспортная лицензия" / "Export License"',
  '- rep_document: "Документ представителя" / "Representative Doc"'
].join('\n');

const userMessage = `Письмо от поставщика:
От: ${from}
Тема: ${subject}
Канал: ${source}

ПРИКРЕПЛЁННЫЕ ФАЙЛЫ (${attachments.length} шт.):
${attachmentList}

Текст письма:
${text.substring(0, 2000)}

---
Проверь наличие документов по именам файлов во вложениях и тексту.
Если файл есть среди вложений — found: true.

Необходимые документы:
${docList}`;

return [{ json: {
  userMessage,
  from,
  subject,
  source,
  attachmentsCount: attachments.length,
  attachmentsList: attachments
}}];

const raw = $input.first().json.output || '{}';
let result;
try {
  result = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  result = { verdict: 'NONE', ready_for_deal: false, missing: [] };
}
return [{ json: { ...result, rawOutput: raw } }];
